// Automatic Traffic Light System using Arduino UNO
const int RED_LED = 12;
const int YELLOW_LED = 11;
const int GREEN_LED = 10;

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
}

void loop() {
  // Red Light - Stop (10 Seconds)
  digitalWrite(RED_LED, HIGH);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(GREEN_LED, LOW);
  delay(10000);

  // Green Light - Go (10 Seconds)
  digitalWrite(RED_LED, LOW);
  digitalWrite(GREEN_LED, HIGH);
  delay(10000);

  // Yellow Light - Prepare (3 Seconds)
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(YELLOW_LED, HIGH);
  delay(3000);
}

// Edge-AI Current Leakage Calculation
float evaluateGridLeakage(float i_phase, float i_neutral) {
  float leakage = fabs(i_phase - i_neutral);
  if (leakage > LEAKAGE_LIMIT_MA) {
    triggerGridRelayTrip();
    publishFaultAlert(leakage);
  }
  return leakage;
}

// Vector Acceleration Fall Detection Algorithm
void checkFallDetection(float ax, float ay, float az, float pitch) {
  float accVector = sqrt(ax*ax + ay*ay + az*az);
  if (accVector > FALL_UPPER_THRESHOLD && fabs(pitch) > 60.0) {
    triggerEmergencyAlert("FALL DETECTED AT LOCATION!");
  }
}

// Gauss-Jordan Row Elimination Core Loop
for (int i = 0; i < n; i++) {
  float pivot = mat[i][i];
  for (int j = 0; j <= n; j++) mat[i][j] /= pivot;
  for (int k = 0; k < n; k++) {
    if (k != i) {
      float factor = mat[k][i];
      for (int j = 0; j <= n; j++) mat[k][j] -= factor * mat[i][j];
    }
  }
}

// Water Quality Index Classification
void classifyWaterSafety(float tdsPPM, float pHValue, float turbidityNTU) {
  if (tdsPPM < 300 && pHValue >= 6.5 && pHValue <= 8.5 && turbidityNTU < 5) {
    setTrafficLight(COLOR_GREEN); // Safe drinking water
  } else if (tdsPPM < 600 && pHValue >= 6.0 && pHValue <= 9.0) {
    setTrafficLight(COLOR_YELLOW); // Moderate / Industrial use
  } else {
    setTrafficLight(COLOR_RED); // Contaminated / Unsafe
  }
}
